UPDATE "partner_programs"
SET "long_description" = CASE "slug"
  WHEN 'clickworker' THEN 'A Clickworker reúne microtarefas de pesquisa, classificação, verificação, criação de textos e coleta de dados para projetos digitais. Depois do cadastro, algumas tarefas podem exigir avaliações ou qualificações específicas. A plataforma mostra as atividades disponíveis para o seu perfil, mas o volume muda conforme país, idioma, demanda e precisão do trabalho. É uma porta de entrada para testar tarefas online sem precisar vender um serviço completo, embora o valor por atividade possa ser pequeno. Comece lendo o briefing, estime o tempo necessário e acompanhe quanto você realmente recebe por hora. Nunca pague alguém para liberar tarefas e use somente o endereço oficial.'
  WHEN 'joinbrands' THEN 'A JoinBrands conecta criadores a campanhas de conteúdo gerado por usuários, o chamado UGC. Você pode produzir vídeos curtos, demonstrações, unboxings ou depoimentos seguindo um briefing da marca, muitas vezes usando apenas o celular e produtos que já possui. O diferencial é que a campanha pode valorizar a qualidade e a clareza do conteúdo, não apenas o número de seguidores. Cada oportunidade tem requisitos, prazo, formato e remuneração próprios. Antes de aceitar, confira se a entrega cabe na sua rotina, se o uso da imagem está claro e se o pagamento está descrito na plataforma.'
  WHEN 'aligner' THEN 'A Aligner apresenta oportunidades para avaliar, comparar e melhorar conteúdos usados no treinamento de sistemas de inteligência artificial. As tarefas podem envolver leitura, escrita, classificação, raciocínio ou revisão de respostas conforme critérios definidos. O processo costuma depender de cadastro, seleção e aprovação em avaliações, e nem todo perfil recebe projetos imediatamente. A remuneração, a quantidade de tarefas e a elegibilidade variam por projeto, país e especialidade. Faça os testes com calma, registre o tempo gasto e nunca confunda uma estimativa de remuneração com renda garantida.'
  WHEN 'marketplaces-afiliados' THEN 'Programas de afiliados de marketplaces permitem recomendar produtos por links rastreáveis e receber comissão quando uma compra qualificada acontece. O caminho mais sustentável é escolher um tema, comparar produtos com honestidade, criar conteúdo útil e acompanhar cliques, conversões e cancelamentos. As taxas variam conforme loja, categoria, campanha e prazo de atribuição; algumas compras não geram comissão. Evite copiar descrições ou fazer spam em grupos. O resultado depende da confiança do público, da qualidade da recomendação e da constância da divulgação.'
  WHEN 'upwork' THEN 'A Upwork aproxima freelancers e clientes em projetos de redação, design, programação, tradução, suporte, marketing e muitas outras áreas. Você monta um perfil, apresenta experiências e envia propostas para trabalhos que combinam com sua habilidade. Um bom início é escolher um serviço específico, montar exemplos claros e explicar como você resolveria o problema do cliente. Há concorrência, taxas e critérios de aprovação, e a quantidade de convites varia. A plataforma não garante contratos: sua renda depende da demanda, da proposta, da entrega e das avaliações recebidas.'
  WHEN 'hotmart' THEN 'Na Hotmart, o afiliado escolhe produtos digitais de uma área que conhece, recebe um link rastreável e cria divulgação para um público compatível. Você pode trabalhar com cursos, ebooks, eventos e outros formatos, sempre verificando a página de vendas, as regras do produtor, a comissão e o prazo de reembolso. Não é necessário criar o produto, mas é preciso construir confiança e explicar a oferta sem prometer resultado. O valor final depende das vendas aprovadas, do preço, da comissão e dos cancelamentos. Conteúdo útil costuma ser mais forte do que publicar links sem contexto.'
  WHEN 'sideshift' THEN 'A SideShift é uma plataforma de troca de ativos digitais com fluxo voltado para operações rápidas e sem conta tradicional em algumas modalidades. Antes de usar, confira quais ativos estão disponíveis, a cotação apresentada, as taxas, o endereço de recebimento e a rede correta. Criptoativos envolvem volatilidade, risco de perda e possíveis exigências regulatórias; não use dinheiro que você não pode perder. Este catálogo não é recomendação financeira. A oportunidade aqui é conhecer uma ferramenta, não uma promessa de renda. Faça uma transação pequena apenas depois de entender todas as etapas.'
  WHEN 'oneforma' THEN 'A OneForma reúne projetos de dados para inteligência artificial, incluindo gravações de voz, transcrição, tradução, anotação e avaliação de conteúdo. O cadastro normalmente começa com um perfil detalhado e pode incluir testes de idioma, equipamento ou qualidade. Cada projeto define país, disponibilidade, prazo, volume e forma de pagamento. Algumas oportunidades são pontuais e outras dependem de aprovação para uma fila de tarefas. Leia o contrato e as instruções antes de enviar material, mantenha seus dados atualizados e nunca aceite cobrança para participar de um projeto oficial.'
  WHEN 'crowdato' THEN 'A Crowdato reúne tarefas digitais e oportunidades ligadas a dados, pesquisa e avaliação de conteúdo. O participante cria um perfil, verifica as qualificações exigidas e se candidata às atividades compatíveis com idioma, localização e experiência. A quantidade de trabalho pode variar bastante e algumas tarefas dependem de revisão de qualidade. Use o primeiro projeto para medir o tempo real por entrega, entender as regras e confirmar o calendário de pagamento. Como em qualquer plataforma de trabalho sob demanda, cadastro não significa volume fixo nem remuneração garantida.'
  WHEN 'claru-ia' THEN 'A Claru IA apresenta oportunidades relacionadas à avaliação, revisão e treinamento de sistemas de inteligência artificial. As atividades podem pedir atenção a critérios, leitura cuidadosa, comparação de respostas ou conhecimento específico de um tema. Confira o escopo, a forma de correção e o requisito de aprovação antes de começar. A disponibilidade e o valor variam conforme a campanha, o país e o perfil do colaborador. Use somente canais oficiais, proteja seus documentos e desconfie de mensagens que prometam contratação imediata mediante pagamento.'
  WHEN 'flambra' THEN 'A Flambra funciona como uma vitrine de possibilidades de trabalho e renda online em diferentes formatos. Use os filtros para descobrir tarefas, serviços ou campanhas que tenham relação com suas habilidades, mas investigue cada oferta antes de enviar documentos, comprar materiais ou pagar qualquer taxa. Uma boa estratégia é separar as oportunidades por tempo, exigência e forma de pagamento, começando por uma atividade pequena. A plataforma pode ajudar na descoberta; o valor, o contrato e a responsabilidade pela entrega dependem do anunciante ou projeto específico.'
  WHEN 'outlier-ai' THEN 'A Outlier AI reúne projetos de avaliação e refinamento de respostas de inteligência artificial. Dependendo da campanha, o trabalho pode envolver escrita, raciocínio, programação, matemática, revisão de fatos ou análise de instruções. A seleção costuma considerar experiência e desempenho em avaliações, e a oferta de tarefas pode mudar depois da entrada. Leia o guia do projeto, controle o tempo não remunerado de treinamento e confira os termos de pagamento. Projetos internacionais podem ter requisitos de idioma, disponibilidade e elegibilidade diferentes.'
  WHEN 'billo' THEN 'A Billo conecta criadores a campanhas de vídeos UGC para marcas. O processo pode envolver escolher uma campanha, ler o briefing, gravar com o celular e enviar o material para aprovação. Você não precisa transformar o vídeo em uma produção de cinema: luz adequada, áudio compreensível e uma apresentação natural costumam importar mais. Cada campanha informa roteiro, prazo, direitos de uso e pagamento, então leia tudo antes de aceitar. A oferta depende do seu perfil e da demanda, e um vídeo enviado não significa aprovação automática.'
  WHEN 'amazon-influencer' THEN 'O Amazon Influencer permite criar uma vitrine personalizada na Amazon e recomendar produtos por listas, fotos, vídeos e transmissões ao vivo. A inscrição considera contas sociais elegíveis e métricas avaliadas pela própria Amazon; não é correto prometer aprovação apenas por ter seguidores. Quando ocorre uma compra qualificada, pode existir comissão conforme a categoria e as regras do Programa de Associados. Algumas categorias brasileiras chegam a 13% na tabela padrão consultada, mas a taxa varia e não é garantia de ganho. Crie demonstrações honestas, identifique o conteúdo comercial e consulte sempre as políticas e relatórios oficiais.'
  WHEN 'testlio' THEN 'A Testlio conecta testadores a projetos de qualidade para sites, aplicativos, dispositivos e serviços digitais. O participante recebe instruções, configura o ambiente pedido, reproduz cenários e reporta problemas com passos claros, evidências e impacto. Um bom relatório precisa ser reproduzível, não apenas dizer que algo está ruim. Convites, ciclos, requisitos e pagamento dependem do projeto, da região e do desempenho. Antes de aceitar, confira o dispositivo necessário, o prazo e as regras de duplicidade para evitar trabalho rejeitado.'
  WHEN 'mercado-pago' THEN 'O Mercado Pago oferece carteira digital, pagamentos, recebimentos e outras soluções financeiras. Campanhas de indicação podem recompensar quem compartilha um convite quando a pessoa indicada cumpre ações elegíveis dentro do período, mas o valor e os requisitos mudam. Há campanhas específicas para produtos como conta ou soluções para negócios, por isso não prometa uma recompensa sem conferir a tela oficial do aplicativo. Compartilhe com pessoas que realmente podem se beneficiar, explique as condições e acompanhe o status no próprio Mercado Pago.'
  WHEN 'hub' THEN 'A Hub reúne oportunidades digitais e tarefas de conteúdo em um ambiente voltado a criadores. Algumas campanhas podem pedir gravações curtas, demonstrações, imagens ou outras entregas seguindo um briefing. Explore as oportunidades abertas, confira o formato do arquivo, o prazo, os direitos de uso e a forma de pagamento antes de aceitar. A disponibilidade depende do perfil, região e demanda das marcas. Um portfólio simples, com boa iluminação e exemplos objetivos, pode ajudar a demonstrar que você consegue entregar com consistência.'
  WHEN 'fiverr' THEN 'No Fiverr, você cria ofertas de serviços que podem incluir design, redação, edição de vídeo, tradução, tecnologia, voz e marketing. O início costuma ser mais forte quando você escolhe uma entrega específica, mostra exemplos e explica exatamente o que o cliente receberá. Compradores de vários países podem encontrar seu anúncio, mas existe concorrência e a plataforma aplica regras e taxas. A renda depende de demanda, preço, prazo, qualidade e avaliações. Não copie trabalhos de terceiros e confirme o escopo antes de aceitar pedidos.'
  WHEN 'apphub' THEN 'O AppHub reúne oportunidades que podem envolver gravação de vídeos e produção de conteúdo em casa. Para aproveitar melhor, confira as campanhas abertas, leia o briefing inteiro, organize o cenário e grave apenas o que você consegue entregar dentro do prazo. Algumas tarefas podem exigir autorização de imagem, características específicas ou um tipo determinado de enquadramento. A oferta, a remuneração e a aprovação dependem do projeto, do perfil e da região. Não compre equipamentos caros antes de validar se existe uma campanha adequada para você.'
  WHEN 'dataannotation' THEN 'A DataAnnotation reúne tarefas de avaliação, comparação e produção de dados para sistemas de inteligência artificial. Dependendo do projeto, você pode revisar respostas, seguir critérios, escrever explicações ou aplicar conhecimento em programação, matemática e outras áreas. A entrada pode exigir avaliação e a disponibilidade não é igual para todos. Leia as instruções, registre o tempo gasto e verifique a política de pagamento antes de contar com a renda. Use o site oficial: empresas legítimas não cobram taxa para liberar trabalho.'
  WHEN 'honeygain' THEN 'O Honeygain permite compartilhar parte da conexão ociosa do dispositivo em troca de créditos. A ideia é instalar o aplicativo, deixar o serviço funcionando e acompanhar o saldo, mas o retorno depende do país, da demanda, da quantidade de dispositivos e da disponibilidade de tráfego. Não é renda garantida nem substitui uma atividade profissional. Leia a política de privacidade, entenda o uso da conexão e verifique o limite mínimo e as regras de saque antes de instalar. Use uma rede confiável e pare se notar comportamento inesperado.'
  WHEN 'quintoandar-indica-ai' THEN 'No Indica Aí, você pode indicar um imóvel residencial para aluguel ou venda com autorização do proprietário. A comunicação divulgada pelo programa inclui R$ 100 quando o imóvel é publicado e 10% do primeiro aluguel quando uma locação acontece, mas cidades, prazos, critérios, valores e campanhas podem mudar. O fluxo exige dados corretos e contato autorizado; nunca envie nome ou telefone de outra pessoa sem consentimento explícito. Explique ao proprietário por que você quer indicar o imóvel e consulte os termos oficiais antes de contar com qualquer recompensa.'
  WHEN 'utest' THEN 'A uTest oferece ciclos de teste para aplicativos, jogos, sites, dispositivos e serviços digitais. Depois do cadastro, você pode participar de projetos compatíveis com seu dispositivo, país e experiência. O trabalho envolve seguir casos, explorar fluxos, registrar evidências e reportar bugs com precisão. Convites e pagamentos variam por ciclo, e relatórios duplicados ou fora das regras podem ser rejeitados. Comece entendendo o escopo, faça perguntas no fórum do ciclo quando necessário e mantenha seu perfil técnico atualizado.'
  WHEN 'prolific' THEN 'A Prolific conecta participantes a estudos acadêmicos e pesquisas de mercado. Você completa um perfil, recebe convites compatíveis com suas respostas e vê as condições do estudo antes de participar. A quantidade de convites depende do país, da demanda e do seu perfil; não existe garantia de tarefas diárias. Leia as perguntas com atenção, responda de forma consistente e confira as regras de pagamento. É uma opção interessante para usar períodos livres, mas o resultado real varia e não deve ser confundido com salário.'
  WHEN 'oort-datahub' THEN 'O OORT DataHub reúne tarefas de coleta, preparação e anotação de dados para projetos de tecnologia e inteligência artificial. Algumas oportunidades podem envolver imagens, texto, voz ou revisão de informações e exigem um cadastro com critérios específicos. O projeto pode pedir código de indicação, teste de qualidade ou disponibilidade em determinado idioma. Confira o briefing, o método de pagamento e a política de dados antes de enviar qualquer material. A oferta e a remuneração dependem da campanha e não são fixas.'
  ELSE "long_description"
END,
"updated_at" = now()
WHERE "slug" IN (
  'clickworker', 'joinbrands', 'aligner', 'marketplaces-afiliados', 'upwork',
  'hotmart', 'sideshift', 'oneforma', 'crowdato', 'claru-ia', 'flambra',
  'outlier-ai', 'billo', 'amazon-influencer', 'testlio', 'mercado-pago',
  'hub', 'fiverr', 'apphub', 'dataannotation', 'honeygain',
  'quintoandar-indica-ai', 'utest', 'prolific', 'oort-datahub'
);
